import * as THREE from 'three';
import {armCurveWeight,footWeight} from '../dormi-sports-pose.js';
import {createRigidArmMapper} from '../dormi-rigid-arms.js';
import {BOXING_GEOMETRY as G,bagSurfaceGap} from './boxing-layout.js';
const signOf=side=>side==='left'?-1:1;
/** The original poser-owned geometry is borrowed in place, then restored byte for byte. */
export function createBoxingRig({model,poser}={}){
 if(!model?.isObject3D||!poser?.setPose||!poser?.getState)throw TypeError('Boxing requires the original model and poser');
 const pose=poser.getState(),saved=[],records=[],hands={left:[],right:[]},soles={left:[],right:[]},face=[],arms=createRigidArmMapper(),source=new THREE.Vector3(),v=new THREE.Vector3();let alive=true,frame=null,applications=0;
 model.traverse(mesh=>{if(mesh.isMesh)saved.push({mesh,g:mesh.geometry,p:mesh.geometry.attributes.position.array.slice(),n:mesh.geometry.attributes.normal?.array.slice(),box:mesh.geometry.boundingBox?.clone(),sphere:mesh.geometry.boundingSphere?.clone()});});
 function restore(){poser.setPose(pose.name,pose.amount,pose.time);for(const r of saved){r.mesh.geometry=r.g;r.g.attributes.position.array.set(r.p);r.g.attributes.position.needsUpdate=true;if(r.n){r.g.attributes.normal.array.set(r.n);r.g.attributes.normal.needsUpdate=true;}r.g.boundingBox=r.box?.clone()??null;r.g.boundingSphere=r.sphere?.clone()??null;}}
 try{poser.setPose('stand',0,0);model.updateWorldMatrix(true,true);const inverse=model.matrixWorld.clone().invert();for(const r of saved){const matrix=inverse.clone().multiply(r.mesh.matrixWorld),a=r.g.attributes.position,rest=new Float32Array(a.count*3),active=[];for(let i=0;i<a.count;i++){v.fromBufferAttribute(a,i).applyMatrix4(matrix);rest.set(v.toArray(),i*3);if(['Dormi_body','Navy_belly_spiral','Belly_spiral_rounded_tip'].includes(r.mesh.name)&&(armCurveWeight(v.x,v.y)>0||footWeight(v.x,v.y,v.z)>0))active.push(i);if(r.mesh.name==='Dormi_body'){const side=v.x<0?'left':'right';if(Math.abs(v.x)>.52&&v.y<.46&&v.y>.25)hands[side].push(v.clone());if(v.y<.002&&Math.abs(v.x)>.1&&Math.abs(v.x)<.36)soles[side].push(v.clone());}if(/face|eye|cheek|antenna|smile|tongue/i.test(r.mesh.name))face.push(v.clone());}records.push({...r,rest,active,fromRoot:matrix.clone().invert()});}if(!hands.left.length||!hands.right.length||!soles.left.length||!soles.right.length)throw Error('Original hand/sole vertices missing');}catch(error){restore();throw error;}
 const targets={left:.3,right:.3},identity=new THREE.Quaternion(),rotations={left:new THREE.Quaternion(),right:new THREE.Quaternion()},guardRotations={},dodgeRotations={},strikeRotations={},feet={};
 function direction(side,amount){return new THREE.Vector3(signOf(side)*(.12+amount*.20),-.04,.345-amount*.12).normalize();}
 function rotation(side,angle){return new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(signOf(side)*.165,-.33,0).normalize(),direction(side,angle));}
 for(const side of['left','right']){const restDirection=new THREE.Vector3(signOf(side)*.165,-.33,0).normalize();guardRotations[side]=new THREE.Quaternion().setFromUnitVectors(restDirection,new THREE.Vector3(signOf(side)*.10,-.20,.28).normalize());dodgeRotations[side]=new THREE.Quaternion().setFromUnitVectors(restDirection,new THREE.Vector3(signOf(side)*.15,-.31,.10).normalize());}
 function setup(f,targetOverride){for(const side of['left','right']){const amount=f.strike?.side===side?f.strike.extension:0;strikeRotations[side]=rotation(side,targetOverride??targets[side]);// Retract the original arms during the supported sideways sway so the near
  // guard hand cannot clip the fixed pad. This is rotation, never arm shortening.
  rotations[side].copy(guardRotations[side]).slerp(dodgeRotations[side],THREE.MathUtils.clamp(Math.abs(f.root.x)/.12,0,1)).slerp(strikeRotations[side],amount);rotations[side].slerp(identity,1-(f.guard??1));const p=f.feet[side];feet[side]=new THREE.Vector3(p.x-f.root.x-signOf(side)*.21,p.y-f.root.y,p.z-f.root.z);}arms.setRotations(rotations);}
 function deform(x,y,z,out){arms.map(source.set(x,y,z),out);out.addScaledVector(feet[x<0?'left':'right'],footWeight(x,y,z));return out;}
 // Solve only a shoulder rotation against fixed emitted pad surfaces. The
 // original source limb length/shape and the equipment position never change.
 for(const side of['left','right']){const f={root:{x:0,y:G.floorY,z:0},feet:{left:{x:-.21,y:G.floorY,z:0},right:{x:.21,y:G.floorY,z:0}},strike:{side,extension:1},guard:1};let lo=0,hi=1.5;for(let n=0;n<40;n++){const angle=(lo+hi)/2;setup(f,angle);let gap=Infinity;for(const p of hands[side]){deform(p.x,p.y,p.z,v);v.y+=G.floorY-G.bagY;v.z-=G.bagZ;gap=Math.min(gap,bagSurfaceGap(v));}if(gap>0)lo=angle;else hi=angle;}targets[side]=(lo+hi)/2;}
 function apply(f){if(!alive)throw Error('Boxing rig released');if(!f?.root||!f?.feet?.left||!f?.feet?.right)throw TypeError('Boxing frame missing support');frame=structuredClone(f);setup(f);for(const r of records){if(!r.active.length)continue;const a=r.g.attributes.position;for(const i of r.active){const k=i*3;deform(r.rest[k],r.rest[k+1],r.rest[k+2],v).applyMatrix4(r.fromRoot);a.setXYZ(i,v.x,v.y,v.z);}a.needsUpdate=true;r.g.computeVertexNormals();r.g.computeBoundingBox();r.g.computeBoundingSphere();}applications++;return frame;}
 function probe(f,station){if(!alive)throw Error('Boxing rig released');setup(f);station.machine.updateWorldMatrix(true,true);const toBag=station.bag.matrixWorld.clone().invert().multiply(station.machine.matrixWorld).multiply(new THREE.Matrix4().makeTranslation(f.root.x,f.root.y,f.root.z));let gap=Infinity,near=0,faceClearance=Infinity,supportGap=0;const side=f.strike?.side;if(side){for(const p of hands[side]){deform(p.x,p.y,p.z,v).applyMatrix4(toBag);const d=bagSurfaceGap(v);gap=Math.min(gap,d);if(Math.abs(d)<.004)near++;}}
  for(const p of face){v.copy(p).applyMatrix4(toBag);faceClearance=Math.min(faceClearance,bagSurfaceGap(v));}
  const toMat=station.mat.matrixWorld.clone().invert().multiply(station.machine.matrixWorld).multiply(new THREE.Matrix4().makeTranslation(f.root.x,f.root.y,f.root.z)),shape=station.mat.geometry.parameters;
  for(const s of['left','right']){let bottom=Infinity;for(const p of soles[s]){deform(p.x,p.y,p.z,v).applyMatrix4(toMat);if(Math.abs(v.x)<=shape.width/2&&Math.abs(v.z)<=shape.depth/2)bottom=Math.min(bottom,v.y-shape.height/2);}supportGap=Math.max(supportGap,Math.abs(bottom));}
  return{side,gap,handVertices:near,faceClearance,supportGap,rootX:f.root.x};
 }
 return{apply,probe,getFrame:()=>frame,release({restore:doRestore=true}={}){if(!alive)return;if(doRestore)restore();alive=false;frame=null;},diagnostics:()=>({actorClones:0,newGeometries:0,newMaterials:0,applications,handVertices:hands.left.length+hands.right.length,contactTargets:{...targets},released:!alive})};
}
